--> statement-breakpoint\nDROP TABLE `_task_2b_voice_preflight`;\n--> statement-breakpoint\nCREATE TABLE `household_billing_accounts` (\n\t`household_id` text PRIMARY KEY NOT NULL,\n\t`customer_id` text,\n\t`subscription_id` text,\n\t`price_id` text,\n\t`status` text DEFAULT 'free' NOT NULL,\n\t`subscription_event_created_at` integer,\n\t`checkout_pending_at` integer,\n\t`checkout_operation_id` text,\n\t`checkout_session_id` text,\n\t`checkout_session_url` text,\n\t`checkout_price_id` text,\n\t`checkout_status` text,\n\t`checkout_expires_at` integer,\n\t`last_credited_invoice_id` text,\n\t`last_credited_period_start` integer,\n\t`created_at` integer NOT NULL,\n\t`updated_at` integer NOT NULL,\n\tFOREIGN KEY (`household_id`) REFERENCES `households`(`id`) ON UPDATE no action ON DELETE cascade\n);\n--> statement-breakpoint\nCREATE UNIQUE INDEX `household_billing_customer_idx` ON `household_billing_accounts` (`customer_id`);\n--> statement-breakpoint\nCREATE UNIQUE INDEX `household_billing_subscription_idx` ON `household_billing_accounts` (`subscription_id`);\n--> statement-breakpoint\nCREATE UNIQUE INDEX `household_billing_checkout_session_idx` ON `household_billing_accounts` (`checkout_session_id`);\n--> statement-breakpoint\nCREATE TABLE `household_billing_subscriptions` (\n\t`subscription_id` text PRIMARY KEY NOT NULL,\n\t`household_id` text NOT NULL,\n\t`customer_id` text NOT NULL,\n\t`price_id` text,\n\t`status` text NOT NULL,\n\t`event_created_at` integer,\n\t`superseded_at` integer,\n\t`created_at` integer NOT NULL,\n\t`updated_at` integer NOT NULL,\n\tFOREIGN KEY (`household_id`) REFERENCES `households`(`id`) ON UPDATE no action ON DELETE cascade\n);\n--> statement-breakpoint\nCREATE INDEX `household_billing_subscriptions_household_idx` ON `household_billing_subscriptions` (`household_id`,`updated_at`);\n--> statement-breakpoint\nALTER TABLE `entitlements` ADD `billing_period_start` integer;\n--> statement-breakpoint\nUPDATE `entitlements` SET `billing_period_start` = CAST(`valid_from` / 1000 AS integer)\nWHERE `external_ref` IS NOT NULL;\n--> statement-breakpoint\nALTER TABLE `stripe_events` ADD `attempt_token` text;\n--> statement-breakpoint\nALTER TABLE `voices` ADD `creation_request_id` text;\n--> statement-breakpoint\nCREATE UNIQUE INDEX `voices_household_user_live_idx` ON `voices` (`household_id`,`user_id`) WHERE \"voices\".\"household_id\" IS NOT NULL AND \"voices\".\"status\" IN ('processing', 'ready');\n--> statement-breakpoint\nCREATE UNIQUE INDEX `voices_household_creation_request_idx` ON `voices` (`household_id`,`creation_request_id`);\n--> statement-breakpoint\nINSERT INTO `household_billing_accounts`\n  (`household_id`, `customer_id`, `subscription_id`, `price_id`, `status`, `subscription_event_created_at`, `checkout_pending_at`, `last_credited_invoice_id`, `last_credited_period_start`, `created_at`, `updated_at`)\nSELECT\n  `households`.`id`, `users`.`stripe_customer_id`, `users`.`subscription_id`, `users`.`subscription_price_id`,\n  `users`.`subscription_status`, `users`.`subscription_event_created_at`, `users`.`checkout_pending_at`,\n  `users`.`last_credited_invoice_id`, `users`.`last_credited_period_start`, `households`.`created_at`, `households`.`updated_at`\nFROM `households`\nJOIN `users` ON `households`.`id` = 'household:' || `users`.`id`;\n--> statement-breakpoint\nINSERT INTO `household_billing_subscriptions`\n  (`subscription_id`, `household_id`, `customer_id`, `price_id`, `status`, `event_created_at`, `created_at`, `updated_at`)\nSELECT `subscription_id`, `household_id`, `customer_id`, `price_id`, `status`, `subscription_event_created_at`, `created_at`, `updated_at`\nFROM `household_billing_accounts`\nWHERE `subscription_id` IS NOT NULL AND `customer_id` IS NOT NULL;\n--> statement-breakpoint\nUPDATE `voice_consents`\nSET `status` = 'revoked', `revoked_at` = COALESCE(`revoked_at`, unixepoch('subsec') * 1000)\nWHERE `status` = 'active_verified' AND `voice_id` IS NOT NULL\n  AND `id` <> COALESCE((SELECT `current_consent_id` FROM `voices` WHERE `voices`.`id` = `voice_consents`.`voice_id`), '');\n--> statement-breakpoint\nDROP INDEX `voice_consents_voice_version_idx`;\n--> statement-breakpoint\nCREATE INDEX `voice_consents_voice_version_idx` ON `voice_consents` (`voice_id`,`consent_version`);\n--> statement-breakpoint\nCREATE UNIQUE INDEX `voice_consents_active_voice_idx` ON `voice_consents` (`voice_id`) WHERE `voice_id` IS NOT NULL AND `status` = 'active_verified';\n--> statement-breakpoint\nCREATE TRIGGER `voice_consents_rotate_active_receipt`\nBEFORE INSERT ON `voice_consents`\nWHEN NEW.`voice_id` IS NOT NULL AND NEW.`status` = 'active_verified'\nBEGIN\n  UPDATE `voice_consents`\n  SET `status` = 'revoked', `revoked_at` = COALESCE(`revoked_at`, NEW.`attested_at`)\n  WHERE `voice_id` = NEW.`voice_id` AND `status` = 'active_verified';\nEND;\n--> statement-breakpoint\nCREATE TRIGGER `voice_consent_leases_require_current_version_insert`\nBEFORE INSERT ON `voice_consent_leases`\nWHEN NEW.`consent_version` <> 'voice-v2-live-phrase'\nBEGIN SELECT RAISE(ABORT, 'voice_consent_version_not_current'); END;\n--> statement-breakpoint\nCREATE TRIGGER `voice_consent_leases_require_current_version_consume`\nBEFORE UPDATE OF `status` ON `voice_consent_leases`\nWHEN NEW.`status` = 'consumed' AND NEW.`consent_version` <> 'voice-v2-live-phrase'\nBEGIN SELECT RAISE(ABORT, 'voice_consent_version_not_current'); END;\n--> statement-breakpoint\nCREATE TRIGGER `usage_reservations_require_current_consent_version`\nBEFORE INSERT ON `usage_reservations`\nWHEN NEW.`consent_lease_id` IS NOT NULL AND NOT EXISTS (\n  SELECT 1 FROM `voice_consent_leases`\n  WHERE `id` = NEW.`consent_lease_id` AND `household_id` = NEW.`household_id`\n    AND `consent_version` = 'voice-v2-live-phrase'\n)\nBEGIN SELECT RAISE(ABORT, 'voice_consent_version_not_current'); END;\n--> statement-breakpoint\nCREATE TRIGGER `sleep_sessions_require_current_consent_version_ready`\nBEFORE UPDATE OF `status` ON `sleep_sessions`\nWHEN NEW.`status` = 'ready' AND NEW.`consent_lease_id` IS NOT NULL\n  AND (NEW.`consent_version` <> 'voice-v2-live-phrase' OR NOT EXISTS (\n    SELECT 1 FROM `voice_consent_leases`\n    WHERE `id` = NEW.`consent_lease_id` AND `household_id` = NEW.`household_id`\n      AND `consent_version` = 'voice-v2-live-phrase'\n  ))\nBEGIN SELECT RAISE(ABORT, 'voice_consent_version_not_current'); END;\n--> statement-breakpoint\nCREATE TRIGGER `child_profiles_validate_household_capacity_insert`\nBEFORE INSERT ON `child_profiles`\nWHEN NEW.`archived_at` IS NULL\nBEGIN\n  SELECT CASE WHEN (SELECT COUNT(*) FROM `child_profiles` WHERE `household_id` = NEW.`household_id` AND `archived_at` IS NULL) >= CASE (\n    SELECT `plan_id` FROM `entitlements` WHERE `household_id` = NEW.`household_id`\n      AND `status` IN ('active', 'grace') AND `valid_from` <= unixepoch('subsec') * 1000\n      AND (`valid_until` IS NULL OR `valid_until` > unixepoch('subsec') * 1000)\n    ORDER BY CASE WHEN `plan_id` = 'nearsleep_free' THEN 0 ELSE 1 END DESC,\n      CASE WHEN `status` = 'active' THEN 1 ELSE 0 END DESC, `updated_at` DESC LIMIT 1\n  ) WHEN 'nearyou_family' THEN 5 WHEN 'nearlegacy' THEN 5 WHEN 'nearsleep_plus_legacy' THEN 3 WHEN 'nearyou_plus' THEN 2 WHEN 'nearsleep_free' THEN 1 ELSE 0 END\n  THEN RAISE(ABORT, 'household_child_limit_reached') END;\nEND;\n--> statement-breakpoint\nCREATE TRIGGER `child_profiles_validate_household_capacity_restore`\nBEFORE UPDATE OF `archived_at` ON `child_profiles`\nWHEN OLD.`archived_at` IS NOT NULL AND NEW.`archived_at` IS NULL\nBEGIN\n  SELECT CASE WHEN (SELECT COUNT(*) FROM `child_profiles` WHERE `household_id` = NEW.`household_id` AND `archived_at` IS NULL) >= CASE (\n    SELECT `plan_id` FROM `entitlements` WHERE `household_id` = NEW.`household_id`\n      AND `status` IN ('active', 'grace') AND `valid_from` <= unixepoch('subsec') * 1000\n      AND (`valid_until` IS NULL OR `valid_until` > unixepoch('subsec') * 1000)\n    ORDER BY CASE WHEN `plan_id` = 'nearsleep_free' THEN 0 ELSE 1 END DESC,\n      CASE WHEN `status` = 'active' THEN 1 ELSE 0 END DESC, `updated_at` DESC LIMIT 1\n  ) WHEN 'nearyou_family' THEN 5 WHEN 'nearlegacy' THEN 5 WHEN 'nearsleep_plus_legacy' THEN 3 WHEN 'nearyou_plus' THEN 2 WHEN 'nearsleep_free' THEN 1 ELSE 0 END\n  THEN RAISE(ABORT, 'household_child_limit_reached') END;\nEND;\n--> statement-breakpoint\nCREATE TRIGGER `voices_validate_household_slot_insert`\nBEFORE INSERT ON `voices`\nWHEN NEW.`household_id` IS NOT NULL AND NEW.`status` IN ('processing', 'ready')\nBEGIN\n  SELECT CASE WHEN NOT EXISTS (\n    SELECT 1 FROM `entitlements` WHERE `household_id` = NEW.`household_id`\n      AND `status` IN ('active', 'grace') AND `valid_from` <= unixepoch('subsec') * 1000\n      AND (`valid_until` IS NULL OR `valid_until` > unixepoch('subsec') * 1000)\n      AND `plan_id` IN ('nearsleep_free', 'nearsleep_plus_legacy', 'nearyou_plus', 'nearyou_family', 'nearlegacy')\n  ) THEN RAISE(ABORT, 'voice_entitlement_required') END;\n  SELECT CASE WHEN NEW.`creation_request_id` IS NOT NULL AND (\n    SELECT `plan_id` FROM `entitlements` WHERE `household_id` = NEW.`household_id`\n      AND `status` IN ('active', 'grace') AND `valid_from` <= unixepoch('subsec') * 1000\n      AND (`valid_until` IS NULL OR `valid_until` > unixepoch('subsec') * 1000)\n    ORDER BY CASE WHEN `plan_id` = 'nearsleep_free' THEN 0 ELSE 1 END DESC,\n      CASE WHEN `status` = 'active' THEN 1 ELSE 0 END DESC, `updated_at` DESC LIMIT 1\n  ) = 'nearsleep_free' THEN RAISE(ABORT, 'free_voice_clone_unavailable') END;\n  SELECT CASE WHEN (SELECT COUNT(*) FROM `voices` WHERE `household_id` = NEW.`household_id` AND `status` IN ('processing', 'ready')) >= CASE (\n    SELECT `plan_id` FROM `entitlements` WHERE `household_id` = NEW.`household_id`\n      AND `status` IN ('active', 'grace') AND `valid_from` <= unixepoch('subsec') * 1000\n      AND (`valid_until` IS NULL OR `valid_until` > unixepoch('subsec') * 1000)\n    ORDER BY CASE WHEN `plan_id` = 'nearsleep_free' THEN 0 ELSE 1 END DESC,\n      CASE WHEN `status` = 'active' THEN 1 ELSE 0 END DESC, `updated_at` DESC LIMIT 1\n  ) WHEN 'nearyou_family' THEN 2 WHEN 'nearlegacy' THEN 5 ELSE 1 END\n  THEN RAISE(ABORT, 'household_voice_limit_reached') END;\nEND;\n--> statement-breakpoint\nCREATE TRIGGER `voices_validate_household_slot_update`\nBEFORE UPDATE OF `status` ON `voices`\nWHEN NEW.`household_id` IS NOT NULL AND NEW.`status` IN ('processing', 'ready') AND OLD.`status` NOT IN ('processing', 'ready')\nBEGIN\n  SELECT CASE WHEN (SELECT COUNT(*) FROM `voices` WHERE `household_id` = NEW.`household_id` AND `status` IN ('processing', 'ready')) >= CASE (\n    SELECT `plan_id` FROM `entitlements` WHERE `household_id` = NEW.`household_id`\n      AND `status` IN ('active', 'grace') AND `valid_from` <= unixepoch('subsec') * 1000\n      AND (`valid_until` IS NULL OR `valid_until` > unixepoch('subsec') * 1000)\n    ORDER BY CASE WHEN `plan_id` = 'nearsleep_free' THEN 0 ELSE 1 END DESC,\n      CASE WHEN `status` = 'active' THEN 1 ELSE 0 END DESC, `updated_at` DESC LIMIT 1\n  ) WHEN 'nearyou_family' THEN 2 WHEN 'nearlegacy' THEN 5 WHEN 'nearsleep_free' THEN 1 WHEN 'nearsleep_plus_legacy' THEN 1 WHEN 'nearyou_plus' THEN 1 ELSE 0 END\n  THEN RAISE(ABORT, 'household_voice_limit_reached') END;\nEND;\n--> statement-breakpoint\nCREATE TRIGGER `voices_protect_live_tenant_binding`\nBEFORE UPDATE OF `household_id`, `user_id` ON `voices`\nWHEN OLD.`status` IN ('processing', 'ready') AND (NEW.`household_id` IS NOT OLD.`household_id` OR NEW.`user_id` IS NOT OLD.`user_id`)\nBEGIN SELECT RAISE(ABORT, 'voice_tenant_binding_immutable'); END;\n--> statement-breakpoint\nCREATE TRIGGER `voices_revoke_superseded_consent`\nAFTER UPDATE OF `current_consent_id` ON `voices`\nWHEN OLD.`current_consent_id` IS NOT NULL AND NEW.`current_consent_id` IS NOT OLD.`current_consent_id`\nBEGIN\n  UPDATE `voice_consents`\n  SET `status` = 'revoked', `revoked_at` = COALESCE(`revoked_at`, unixepoch('subsec') * 1000)\n  WHERE `id` = OLD.`current_consent_id` AND `household_id` = NEW.`household_id`\n    AND `voice_id` = NEW.`id` AND `status` IN ('pending_verification', 'active_verified');\nEND;\n--> statement-breakpoint\nCREATE TRIGGER `voice_replacements_prepare_first_clone`\nBEFORE UPDATE OF `status` ON `voice_replacements`\nWHEN OLD.`status` = 'provider_created' AND NEW.`status` = 'activating'\n  AND NEW.`original_provider_voice_id` LIKE 'pending:%'\nBEGIN\n  UPDATE `voices` SET `status` = 'ready'\n  WHERE `id` = NEW.`voice_id` AND `household_id` = NEW.`household_id` AND `user_id` = NEW.`adult_user_id`\n    AND `status` = 'processing' AND `provider_voice_id` = NEW.`original_provider_voice_id`\n    AND `current_consent_id` = NEW.`original_consent_id`;\n  SELECT CASE WHEN changes() <> 1 THEN RAISE(ABORT, 'voice_first_clone_activation_cas_failed') END;\nEND;\n","statements":["CREATE TABLE IF NOT EXISTS `_task_2b_voice_preflight` (\n  `duplicate_live_voice_count` integer NOT NULL,\n  CONSTRAINT `task_2b_duplicate_live_voice_preflight` CHECK (`duplicate_live_voice_count` = 0)\n);","DELETE FROM `_task_2b_voice_preflight`;","INSERT INTO `_task_2b_voice_preflight` (`duplicate_live_voice_count`)\nSELECT COALESCE(SUM(`live_count` - 1), 0)\nFROM (\n  SELECT COUNT(*) AS `live_count`\n  FROM `voices`\n  WHERE `household_id` IS NOT NULL AND `status` IN ('processing', 'ready')\n  GROUP BY `household_id`, `user_id`\n  HAVING COUNT(*) > 1\n);","DROP TABLE `_task_2b_voice_preflight`;","CREATE TABLE `household_billing_accounts` (\n\t`household_id` text PRIMARY KEY NOT NULL,\n\t`customer_id` text,\n\t`subscription_id` text,\n\t`price_id` text,\n\t`status` text DEFAULT 'free' NOT NULL,\n\t`subscription_event_created_at` integer,\n\t`checkout_pending_at` integer,\n\t`checkout_operation_id` text,\n\t`checkout_session_id` text,\n\t`checkout_session_url` text,\n\t`checkout_price_id` text,\n\t`checkout_status` text,\n\t`checkout_expires_at` integer,\n\t`last_credited_invoice_id` text,\n\t`last_credited_period_start` integer,\n\t`created_at` integer NOT NULL,\n\t`updated_at` integer NOT NULL,\n\tFOREIGN KEY (`household_id`) REFERENCES `households`(`id`) ON UPDATE no action ON DELETE cascade\n);","CREATE UNIQUE INDEX `household_billing_customer_idx` ON `household_billing_accounts` (`customer_id`);","CREATE UNIQUE INDEX `household_billing_subscription_idx` ON `household_billing_accounts` (`subscription_id`);","CREATE UNIQUE INDEX `household_billing_checkout_session_idx` ON `household_billing_accounts` (`checkout_session_id`);","CREATE TABLE `household_billing_subscriptions` (\n\t`subscription_id` text PRIMARY KEY NOT NULL,\n\t`household_id` text NOT NULL,\n\t`customer_id` text NOT NULL,\n\t`price_id` text,\n\t`status` text NOT NULL,\n\t`event_created_at` integer,\n\t`superseded_at` integer,\n\t`created_at` integer NOT NULL,\n\t`updated_at` integer NOT NULL,\n\tFOREIGN KEY (`household_id`) REFERENCES `households`(`id`) ON UPDATE no action ON DELETE cascade\n);","CREATE INDEX `household_billing_subscriptions_household_idx` ON `household_billing_subscriptions` (`household_id`,`updated_at`);","ALTER TABLE `entitlements` ADD `billing_period_start` integer;","UPDATE `entitlements` SET `billing_period_start` = CAST(`valid_from` / 1000 AS integer)\nWHERE `external_ref` IS NOT NULL;","ALTER TABLE `stripe_events` ADD `attempt_token` text;","ALTER TABLE `voices` ADD `creation_request_id` text;","CREATE UNIQUE INDEX `voices_household_user_live_idx` ON `voices` (`household_id`,`user_id`) WHERE \"voices\".\"household_id\" IS NOT NULL AND \"voices\".\"status\" IN ('processing', 'ready');","CREATE UNIQUE INDEX `voices_household_creation_request_idx` ON `voices` (`household_id`,`creation_request_id`);","INSERT INTO `household_billing_accounts`\n  (`household_id`, `customer_id`, `subscription_id`, `price_id`, `status`, `subscription_event_created_at`, `checkout_pending_at`, `last_credited_invoice_id`, `last_credited_period_start`, `created_at`, `updated_at`)\nSELECT\n  `households`.`id`, `users`.`stripe_customer_id`, `users`.`subscription_id`, `users`.`subscription_price_id`,\n  `users`.`subscription_status`, `users`.`subscription_event_created_at`, `users`.`checkout_pending_at`,\n  `users`.`last_credited_invoice_id`, `users`.`last_credited_period_start`, `households`.`created_at`, `households`.`updated_at`\nFROM `households`\nJOIN `users` ON `households`.`id` = 'household:' || `users`.`id`;","INSERT INTO `household_billing_subscriptions`\n  (`subscription_id`, `household_id`, `customer_id`, `price_id`, `status`, `event_created_at`, `created_at`, `updated_at`)\nSELECT `subscription_id`, `household_id`, `customer_id`, `price_id`, `status`, `subscription_event_created_at`, `created_at`, `updated_at`\nFROM `household_billing_accounts`\nWHERE `subscription_id` IS NOT NULL AND `customer_id` IS NOT NULL;","UPDATE `voice_consents`\nSET `status` = 'revoked', `revoked_at` = COALESCE(`revoked_at`, unixepoch('subsec') * 1000)\nWHERE `status` = 'active_verified' AND `voice_id` IS NOT NULL\n  AND `id` <> COALESCE((SELECT `current_consent_id` FROM `voices` WHERE `voices`.`id` = `voice_consents`.`voice_id`), '');","DROP INDEX `voice_consents_voice_version_idx`;","CREATE INDEX `voice_consents_voice_version_idx` ON `voice_consents` (`voice_id`,`consent_version`);","CREATE UNIQUE INDEX `voice_consents_active_voice_idx` ON `voice_consents` (`voice_id`) WHERE `voice_id` IS NOT NULL AND `status` = 'active_verified';","CREATE TRIGGER `voice_consents_rotate_active_receipt`\nBEFORE INSERT ON `voice_consents`\nWHEN NEW.`voice_id` IS NOT NULL AND NEW.`status` = 'active_verified'\nBEGIN\n  UPDATE `voice_consents`\n  SET `status` = 'revoked', `revoked_at` = COALESCE(`revoked_at`, NEW.`attested_at`)\n  WHERE `voice_id` = NEW.`voice_id` AND `status` = 'active_verified';\nEND;","CREATE TRIGGER `voice_consent_leases_require_current_version_insert`\nBEFORE INSERT ON `voice_consent_leases`\nWHEN NEW.`consent_version` <> 'voice-v2-live-phrase'\nBEGIN SELECT RAISE(ABORT, 'voice_consent_version_not_current'); END;","CREATE TRIGGER `voice_consent_leases_require_current_version_consume`\nBEFORE UPDATE OF `status` ON `voice_consent_leases`\nWHEN NEW.`status` = 'consumed' AND NEW.`consent_version` <> 'voice-v2-live-phrase'\nBEGIN SELECT RAISE(ABORT, 'voice_consent_version_not_current'); END;","CREATE TRIGGER `usage_reservations_require_current_consent_version`\nBEFORE INSERT ON `usage_reservations`\nWHEN NEW.`consent_lease_id` IS NOT NULL AND NOT EXISTS (\n  SELECT 1 FROM `voice_consent_leases`\n  WHERE `id` = NEW.`consent_lease_id` AND `household_id` = NEW.`household_id`\n    AND `consent_version` = 'voice-v2-live-phrase'\n)\nBEGIN SELECT RAISE(ABORT, 'voice_consent_version_not_current'); END;","CREATE TRIGGER `sleep_sessions_require_current_consent_version_ready`\nBEFORE UPDATE OF `status` ON `sleep_sessions`\nWHEN NEW.`status` = 'ready' AND NEW.`consent_lease_id` IS NOT NULL\n  AND (NEW.`consent_version` <> 'voice-v2-live-phrase' OR NOT EXISTS (\n    SELECT 1 FROM `voice_consent_leases`\n    WHERE `id` = NEW.`consent_lease_id` AND `household_id` = NEW.`household_id`\n      AND `consent_version` = 'voice-v2-live-phrase'\n  ))\nBEGIN SELECT RAISE(ABORT, 'voice_consent_version_not_current'); END;","CREATE TRIGGER `child_profiles_validate_household_capacity_insert`\nBEFORE INSERT ON `child_profiles`\nWHEN NEW.`archived_at` IS NULL\nBEGIN\n  SELECT CASE WHEN (SELECT COUNT(*) FROM `child_profiles` WHERE `household_id` = NEW.`household_id` AND `archived_at` IS NULL) >= CASE (\n    SELECT `plan_id` FROM `entitlements` WHERE `household_id` = NEW.`household_id`\n      AND `status` IN ('active', 'grace') AND `valid_from` <= unixepoch('subsec') * 1000\n      AND (`valid_until` IS NULL OR `valid_until` > unixepoch('subsec') * 1000)\n    ORDER BY CASE WHEN `plan_id` = 'nearsleep_free' THEN 0 ELSE 1 END DESC,\n      CASE WHEN `status` = 'active' THEN 1 ELSE 0 END DESC, `updated_at` DESC LIMIT 1\n  ) WHEN 'nearyou_family' THEN 5 WHEN 'nearlegacy' THEN 5 WHEN 'nearsleep_plus_legacy' THEN 3 WHEN 'nearyou_plus' THEN 2 WHEN 'nearsleep_free' THEN 1 ELSE 0 END\n  THEN RAISE(ABORT, 'household_child_limit_reached') END;\nEND;","CREATE TRIGGER `child_profiles_validate_household_capacity_restore`\nBEFORE UPDATE OF `archived_at` ON `child_profiles`\nWHEN OLD.`archived_at` IS NOT NULL AND NEW.`archived_at` IS NULL\nBEGIN\n  SELECT CASE WHEN (SELECT COUNT(*) FROM `child_profiles` WHERE `household_id` = NEW.`household_id` AND `archived_at` IS NULL) >= CASE (\n    SELECT `plan_id` FROM `entitlements` WHERE `household_id` = NEW.`household_id`\n      AND `status` IN ('active', 'grace') AND `valid_from` <= unixepoch('subsec') * 1000\n      AND (`valid_until` IS NULL OR `valid_until` > unixepoch('subsec') * 1000)\n    ORDER BY CASE WHEN `plan_id` = 'nearsleep_free' THEN 0 ELSE 1 END DESC,\n      CASE WHEN `status` = 'active' THEN 1 ELSE 0 END DESC, `updated_at` DESC LIMIT 1\n  ) WHEN 'nearyou_family' THEN 5 WHEN 'nearlegacy' THEN 5 WHEN 'nearsleep_plus_legacy' THEN 3 WHEN 'nearyou_plus' THEN 2 WHEN 'nearsleep_free' THEN 1 ELSE 0 END\n  THEN RAISE(ABORT, 'household_child_limit_reached') END;\nEND;","CREATE TRIGGER `voices_validate_household_slot_insert`\nBEFORE INSERT ON `voices`\nWHEN NEW.`household_id` IS NOT NULL AND NEW.`status` IN ('processing', 'ready')\nBEGIN\n  SELECT CASE WHEN NOT EXISTS (\n    SELECT 1 FROM `entitlements` WHERE `household_id` = NEW.`household_id`\n      AND `status` IN ('active', 'grace') AND `valid_from` <= unixepoch('subsec') * 1000\n      AND (`valid_until` IS NULL OR `valid_until` > unixepoch('subsec') * 1000)\n      AND `plan_id` IN ('nearsleep_free', 'nearsleep_plus_legacy', 'nearyou_plus', 'nearyou_family', 'nearlegacy')\n  ) THEN RAISE(ABORT, 'voice_entitlement_required') END;\n  SELECT CASE WHEN NEW.`creation_request_id` IS NOT NULL AND (\n    SELECT `plan_id` FROM `entitlements` WHERE `household_id` = NEW.`household_id`\n      AND `status` IN ('active', 'grace') AND `valid_from` <= unixepoch('subsec') * 1000\n      AND (`valid_until` IS NULL OR `valid_until` > unixepoch('subsec') * 1000)\n    ORDER BY CASE WHEN `plan_id` = 'nearsleep_free' THEN 0 ELSE 1 END DESC,\n      CASE WHEN `status` = 'active' THEN 1 ELSE 0 END DESC, `updated_at` DESC LIMIT 1\n  ) = 'nearsleep_free' THEN RAISE(ABORT, 'free_voice_clone_unavailable') END;\n  SELECT CASE WHEN (SELECT COUNT(*) FROM `voices` WHERE `household_id` = NEW.`household_id` AND `status` IN ('processing', 'ready')) >= CASE (\n    SELECT `plan_id` FROM `entitlements` WHERE `household_id` = NEW.`household_id`\n      AND `status` IN ('active', 'grace') AND `valid_from` <= unixepoch('subsec') * 1000\n      AND (`valid_until` IS NULL OR `valid_until` > unixepoch('subsec') * 1000)\n    ORDER BY CASE WHEN `plan_id` = 'nearsleep_free' THEN 0 ELSE 1 END DESC,\n      CASE WHEN `status` = 'active' THEN 1 ELSE 0 END DESC, `updated_at` DESC LIMIT 1\n  ) WHEN 'nearyou_family' THEN 2 WHEN 'nearlegacy' THEN 5 ELSE 1 END\n  THEN RAISE(ABORT, 'household_voice_limit_reached') END;\nEND;","CREATE TRIGGER `voices_validate_household_slot_update`\nBEFORE UPDATE OF `status` ON `voices`\nWHEN NEW.`household_id` IS NOT NULL AND NEW.`status` IN ('processing', 'ready') AND OLD.`status` NOT IN ('processing', 'ready')\nBEGIN\n  SELECT CASE WHEN (SELECT COUNT(*) FROM `voices` WHERE `household_id` = NEW.`household_id` AND `status` IN ('processing', 'ready')) >= CASE (\n    SELECT `plan_id` FROM `entitlements` WHERE `household_id` = NEW.`household_id`\n      AND `status` IN ('active', 'grace') AND `valid_from` <= unixepoch('subsec') * 1000\n      AND (`valid_until` IS NULL OR `valid_until` > unixepoch('subsec') * 1000)\n    ORDER BY CASE WHEN `plan_id` = 'nearsleep_free' THEN 0 ELSE 1 END DESC,\n      CASE WHEN `status` = 'active' THEN 1 ELSE 0 END DESC, `updated_at` DESC LIMIT 1\n  ) WHEN 'nearyou_family' THEN 2 WHEN 'nearlegacy' THEN 5 WHEN 'nearsleep_free' THEN 1 WHEN 'nearsleep_plus_legacy' THEN 1 WHEN 'nearyou_plus' THEN 1 ELSE 0 END\n  THEN RAISE(ABORT, 'household_voice_limit_reached') END;\nEND;","CREATE TRIGGER `voices_protect_live_tenant_binding`\nBEFORE UPDATE OF `household_id`, `user_id` ON `voices`\nWHEN OLD.`status` IN ('processing', 'ready') AND (NEW.`household_id` IS NOT OLD.`household_id` OR NEW.`user_id` IS NOT OLD.`user_id`)\nBEGIN SELECT RAISE(ABORT, 'voice_tenant_binding_immutable'); END;","CREATE TRIGGER `voices_revoke_superseded_consent`\nAFTER UPDATE OF `current_consent_id` ON `voices`\nWHEN OLD.`current_consent_id` IS NOT NULL AND NEW.`current_consent_id` IS NOT OLD.`current_consent_id`\nBEGIN\n  UPDATE `voice_consents`\n  SET `status` = 'revoked', `revoked_at` = COALESCE(`revoked_at`, unixepoch('subsec') * 1000)\n  WHERE `id` = OLD.`current_consent_id` AND `household_id` = NEW.`household_id`\n    AND `voice_id` = NEW.`id` AND `status` IN ('pending_verification', 'active_verified');\nEND;","CREATE TRIGGER `voice_replacements_prepare_first_clone`\nBEFORE UPDATE OF `status` ON `voice_replacements`\nWHEN OLD.`status` = 'provider_created' AND NEW.`status` = 'activating'\n  AND NEW.`original_provider_voice_id` LIKE 'pending:%'\nBEGIN\n  UPDATE `voices` SET `status` = 'ready'\n  WHERE `id` = NEW.`voice_id` AND `household_id` = NEW.`household_id` AND `user_id` = NEW.`adult_user_id`\n    AND `status` = 'processing' AND `provider_voice_id` = NEW.`original_provider_voice_id`\n    AND `current_consent_id` = NEW.`original_consent_id`;\n  SELECT CASE WHEN changes() <> 1 THEN RAISE(ABORT, 'voice_first_clone_activation_cas_failed') END;\nEND;"]},{"id":"0012_nearsleep_library_privacy","sha256":"295346091fdc38f599af621888eb12e250deab1bbbf43e2a11d616c7fcb6de8d","sql":"ALTER TABLE `sleep_sessions` ADD `deletion_status` text DEFAULT 'active' NOT NULL;\n--> statement-breakpoint\nALTER TABLE `sleep_sessions` ADD `deletion_requested_at` integer;\n--> statement-breakpoint\nALTER TABLE `sleep_sessions` ADD `deleted_at` integer;\n--> statement-breakpoint\nCREATE INDEX `sessions_household_library_idx` ON `sleep_sessions` (`household_id`,`deletion_status`,`status`,`created_at`);\n--> statement-breakpoint\nALTER TABLE `deletion_reconciliations` ADD `household_id` text REFERENCES `households`(`id`) ON DELETE cascade;\n--> statement-breakpoint\nALTER TABLE `deletion_reconciliations` ADD `attempt_token` text;\n--> statement-breakpoint\nALTER TABLE `deletion_reconciliations` ADD `attempt_expires_at` integer;\n--> statement-breakpoint\nUPDATE `deletion_reconciliations` SET `household_id` = COALESCE(\n  (SELECT `household_id` FROM `sleep_sessions` WHERE `id` = `deletion_reconciliations`.`scope_id`),\n  (SELECT `household_id` FROM `voices` WHERE `id` = `deletion_reconciliations`.`scope_id`),\n  (SELECT `household_id` FROM `voice_replacements` WHERE `id` = `deletion_reconciliations`.`scope_id`),\n  (SELECT `id` FROM `households` WHERE `id` = `deletion_reconciliations`.`scope_id` AND `deletion_reconciliations`.`scope` = 'account')\n);\n--> statement-breakpoint\nCREATE INDEX `deletion_reconciliations_household_status_idx` ON `deletion_reconciliations` (`household_id`,`status`,`id`);\n--> statement-breakpoint\nCREATE TRIGGER `deletion_reconciliations_bind_household`\nAFTER INSERT ON `deletion_reconciliations` WHEN NEW.`household_id` IS NULL\nBEGIN\n  UPDATE `deletion_reconciliations` SET `household_id` = COALESCE(\n    (SELECT `household_id` FROM `sleep_sessions` WHERE `id` = NEW.`scope_id`),\n    (SELECT `household_id` FROM `voices` WHERE `id` = NEW.`scope_id`),\n    (SELECT `household_id` FROM `voice_replacements` WHERE `id` = NEW.`scope_id`),\n    (SELECT `id` FROM `households` WHERE `id` = NEW.`scope_id` AND NEW.`scope` = 'account')\n  ) WHERE `id` = NEW.`id`;\nEND;\n--> statement-breakpoint\nCREATE TABLE `household_storage_reservations` (\n  `id` text PRIMARY KEY NOT NULL,\n  `household_id` text NOT NULL,\n  `media_asset_id` text NOT NULL,\n  `byte_size` integer NOT NULL,\n  `status` text DEFAULT 'reserved' NOT NULL,\n  `created_at` integer NOT NULL,\n  `updated_at` integer NOT NULL,\n  `released_at` integer,\n  FOREIGN KEY (`household_id`) REFERENCES `households`(`id`) ON DELETE cascade,\n  FOREIGN KEY (`media_asset_id`) REFERENCES `media_assets`(`id`) ON DELETE cascade\n);\n--> statement-breakpoint\nCREATE UNIQUE INDEX `household_storage_media_idx` ON `household_storage_reservations` (`media_asset_id`);\n--> statement-breakpoint\nCREATE INDEX `household_storage_status_idx` ON `household_storage_reservations` (`household_id`,`status`);\n--> statement-breakpoint\nCREATE TABLE `task2c_media_integrity` (\n  `media_asset_id` text PRIMARY KEY NOT NULL,\n  `byte_size` integer NOT NULL,\n  `checksum` text NOT NULL,\n  `verified_at` integer NOT NULL,\n  FOREIGN KEY (`media_asset_id`) REFERENCES `media_assets`(`id`) ON DELETE cascade\n);\n--> statement-breakpoint\nINSERT INTO `household_storage_reservations` (`id`,`household_id`,`media_asset_id`,`byte_size`,`status`,`created_at`,`updated_at`)\nSELECT 'storage:' || `id`, `household_id`, `id`, `byte_size`, 'reserved', `created_at`, `updated_at`\nFROM `media_assets` WHERE `status` = 'ready' AND `byte_size` IS NOT NULL AND `byte_size` > 0;\n--> statement-breakpoint\nUPDATE `household_storage_reservations` SET `status` = 'committed' WHERE `status` = 'reserved' AND EXISTS (SELECT 1 FROM `media_assets` WHERE `media_assets`.`id` = `household_storage_reservations`.`media_asset_id` AND `media_assets`.`status` = 'ready');\n--> statement-breakpoint\nCREATE TABLE `task2c_activation_state` (\n  `id` text PRIMARY KEY NOT NULL,\n  `status` text DEFAULT 'pending' NOT NULL,\n  `unresolved_ready_media` integer DEFAULT 0 NOT NULL,\n  `checked_at` integer NOT NULL,\n  `scheduler_heartbeat_at` integer,\n  `scheduler_run_id` text\n);\n--> statement-breakpoint\nINSERT INTO `task2c_activation_state` (`id`,`status`,`unresolved_ready_media`,`checked_at`)\nSELECT 'storage', CASE WHEN COUNT(*) = 0 THEN 'ready' ELSE 'pending' END, COUNT(*), unixepoch('subsec') * 1000\nFROM `media_assets` m WHERE m.`status` = 'ready' AND (\n  m